        vals = {row[c] for c in range(start, end) if row[c] != 0}
        if len(vals) == 1:
            return next(iter(vals))
        return 0

    # Build mappings from the top example area
    forward = {}
    inverse = {}
    for r in range(sep_row):
        lv = region_value(grid[r], 0, left_end)
        rv = region_value(grid[r], right_start, w)
        if lv != 0 and rv != 0:
            forward[lv] = rv
            inverse[rv] = lv

    out = [row[:] for row in grid]

    # Fill the bottom area using the learned mapping
    for r in range(sep_row + 1, h):
        lv = region_value(out[r], 0, left_end)
